 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    rail = next(v for v in colors if v != bg and any(grid[r][c] == v and (r in (0,h-1) or c in (0,w-1)) for r in range(h) for c in range(w)))
    markers = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (bg,rail)]
    # Edge bar lengths determine alternating interior stripes; use the marker color
    # on cells carrying that bar's matching phase.
    for side in ('left','right','top','bottom'):
        vals = []
        if side == 'left': vals = [grid[r][0] for r in range(h)]
        elif side == 'right': vals = [grid[r][w-1] for r in range(h)]
        elif side == 'top': vals = grid[0][:]
        else: vals = grid[h-1][:]
        indices = [i for i,v in enumerate(vals) if v == rail]
        if not indices: continue
        # The rail's contiguous segment produces every-other stripe parallel to it.
        lo, hi = min(indices), max(indices)
        for idx in range(lo, hi+1, 2):
            if side == 'left':
                for c in range(1,w):
                    if grid[idx][c] == bg: out[idx][c] = markers[0][2]
            elif side == 'right':
                for c in range(w-2,-1,-1):
                    if grid[idx][c] == bg: out[idx][c] = markers[0][2]
            elif side == 'top':
                for r in range(1,h):
                    if grid[r][idx] == bg: out[r][idx] = markers[0][2]
            else:
                for r in range(h-2,-1,-1):
                    if grid[r][idx] == bg: out[r][idx] = markers[0][2]
    # Each isolated marker is highlighted and sends a beam toward the edge
    # rail on its row or column, stopping before the rail itself.
    for r,c,v in markers:
        out[r][c] = 4
        if grid[r][0] == rail:
            for cc in range(c-1,0,-1): out[r][cc] = v
        elif grid[r][-1] == rail:
            for cc in range(c+1,w-1): out[r][cc] = v
        elif grid[0][c] == rail:
            for rr in range(r-1,0,-1): out[rr][c] = v
        elif grid[h-1][c] == rail:
            for rr in range(r+1,h-1): out[rr][c] = v
    return out
