    # A 3-cell edge motif defines the matching 3x3 interior tile. Repeated
    # marker-colored tiles are copied in the direction away from that motif.
    edge_marks = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
                  if grid[r][c] != bg and (r in (0,h-1) or c in (0,w-1))]
    if not edge_marks:
        return out
    # edge motif must be a contiguous run of three cells; its color is retained.
    motif = None
    for r in range(h):
        for c in range(w-2):
            if grid[r][c] == grid[r][c+1] == grid[r][c+2] != bg and r in (0,h-1):
                motif=('h',r,c,grid[r][c]); break
        if motif: break
    if motif is None:
        for c in range(w):
            for r in range(h-2):
                if grid[r][c] == grid[r+1][c] == grid[r+2][c] != bg and c in (0,w-1):
                    motif=('v',r,c,grid[r][c]); break
            if motif: break
    if motif is None:
        return out
    axis, mr, mc, bar = motif
    markers=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (bg,bar)]
    if not markers: return out
    color=markers[0][2]
    # Full runs of the marker color are completed as 2x2 blocks, aligned to the seed.
    for r,c,v in markers:
        out[r][c]=4
        if axis=='h':
            # seed is on row above/below motif; grow away from the edge in 2-row units.
            direction = 1 if mr==0 else -1
            base_r = r
            for dr in (0,1):
                rr=base_r+direction*dr
                if not (0<=rr<h): continue
                for dc in (0,1):
                    cc=c+dc
                    if 0<=cc<w and grid[rr][cc] == bg: out[rr][cc]=v
        else:
            direction = 1 if mc==0 else -1
            for dr in (0,1):
                rr=r+dr
                for dc in (0,1):
                    cc=c+direction*dc
                    if 0<=rr<h and 0<=cc<w and grid[rr][cc] == bg: out[rr][cc]=v
    # Also project established marker-colored 2x2 blocks from the repeated edge motifs.
